import React, { useState, useEffect } from "react";

function Home() {
  const [resumeText, setResumeText] = useState("");
  const [jobDesc, setJobDesc] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [template, setTemplate] = useState("simple");
  const [matchData, setMatchData] = useState(null);
  const [photo, setPhoto] = useState(null);

  // ================= AUTH =================
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) window.location.href = "/login";
  }, []);

  // ================= OPTIMIZE =================
  const handleOptimize = async () => {
    if (!resumeText || !jobDesc) {
      return alert("Provide Resume + Job Description");
    }

    setLoading(true);

    try {
      const token = localStorage.getItem("token");

      const res = await fetch("http://localhost:5000/api/resume/optimize", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`, // ✅ FIXED
        },
        body: JSON.stringify({
          resumeText,
          jobDesc,
          template,
          photo,
        }),
      });

      const data = await res.json();
      setResult(data);

    } catch (err) {
      console.log(err);
      alert("Optimization failed");
    } finally {
      setLoading(false);
    }
  };

  // ================= SAVE =================
  const handleSave = async () => {
    try {
      const token = localStorage.getItem("token");

      if (!result?.optimizedText) {
        return alert("Optimize first");
      }

      await fetch("http://localhost:5000/api/resume/save", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`, // ✅ FIXED
        },
        body: JSON.stringify({
          text: result.optimizedText,
          atsScore: result.score,
        }),
      });

      alert("Saved successfully");

    } catch (err) {
      console.log(err);
      alert("Save failed");
    }
  };

  // ================= MATCH =================
  const handleMatch = async () => {
    try {
      const token = localStorage.getItem("token");

      const res = await fetch("http://localhost:5000/api/resume/match", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ resumeText, jobDesc }),
      });

      const data = await res.json();
      setMatchData(data);

    } catch (err) {
      console.log(err);
      alert("Match failed");
    }
  };

  // ================= PDF → TEXT =================
  const handleResumeUpload = async (e) => {
    const file = e.target.files[0];
    const token = localStorage.getItem("token");

    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://localhost:5000/api/resume/upload-pdf", {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` },
      body: formData,
    });

    const data = await res.json();
    setResumeText(data.text);
  };

  const handleJDUpload = async (e) => {
    const file = e.target.files[0];
    const token = localStorage.getItem("token");

    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://localhost:5000/api/resume/upload-pdf", {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` },
      body: formData,
    });

    const data = await res.json();
    setJobDesc(data.text);
  };

  // ================= PHOTO =================
  const handlePhoto = (e) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      setPhoto(reader.result.split(",")[1]);
    };
    reader.readAsDataURL(e.target.files[0]);
  };

  // ================= DOWNLOAD =================
  const handleDownload = async () => {
    const token = localStorage.getItem("token");

    const res = await fetch("http://localhost:5000/api/resume/download", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        text: result.optimizedText,
        template,
        photo,
      }),
    });

    const blob = await res.blob();
    const url = window.URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = "resume.pdf";
    a.click();
  };

  return (
    <div style={styles.page}>
      <h1 style={styles.logo}>CareerForge Pro 🚀</h1>

      <div style={styles.card}>

        {/* RESUME */}
        <h3 style={styles.heading}>📄 Resume</h3>

        <input type="file" accept=".pdf" onChange={handleResumeUpload} />
        <p style={styles.or}>OR</p>

        <textarea
          placeholder="Paste Resume..."
          value={resumeText}
          onChange={(e) => setResumeText(e.target.value)}
          style={styles.textarea}
        />

        {/* JOB DESC */}
        <h3 style={styles.heading}>💼 Job Description</h3>

        <input type="file" accept=".pdf" onChange={handleJDUpload} />
        <p style={styles.or}>OR</p>

        <textarea
          placeholder="Paste Job Description..."
          value={jobDesc}
          onChange={(e) => setJobDesc(e.target.value)}
          style={styles.textarea}
        />

        {/* PHOTO */}
        <h3 style={styles.heading}>🖼 Upload Photo (optional)</h3>
        <input type="file" onChange={handlePhoto} />

        {/* TEMPLATE */}
        <select
          value={template}
          onChange={(e) => setTemplate(e.target.value)}
          style={styles.select}
        >
          <option value="simple">Simple</option>
          <option value="modern">Modern</option>
          <option value="professional">Professional</option>
          <option value="minimal">Minimal</option>
        </select>

        <button style={styles.primaryBtn} onClick={handleOptimize}>
          {loading ? "Optimizing..." : "Optimize Resume"}
        </button>

        <button style={styles.secondaryBtn} onClick={handleMatch}>
          Check Job Match
        </button>

        <button
          style={styles.secondaryBtn}
          onClick={() => (window.location.href = "/dashboard")}
        >
          Go to Dashboard
        </button>
      </div>

      {/* RESULT */}
      {result && (
        <div style={styles.resultCard}>
          <h2>ATS Score: {result.score}</h2>

          <pre style={styles.output}>{result.optimizedText}</pre>

          <button style={styles.primaryBtn} onClick={handleSave}>
            Save Resume
          </button>

          <button style={styles.primaryBtn} onClick={handleDownload}>
            Download PDF
          </button>
        </div>
      )}

      {/* MATCH */}
      {matchData && (
        <div style={styles.resultCard}>
          <h2>Job Match</h2>
          <p>Score: {matchData.matchScore}</p>
          <p>{matchData.message}</p>

          <ul>
            {matchData.roles.map((r, i) => (
              <li key={i}>{r}</li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

const styles = {
  page: {
    minHeight: "100vh",
    background: "linear-gradient(135deg,#020617,#0f172a)",
    padding: "30px",
    color: "white",
    textAlign: "center",
  },
  logo: { color: "#38bdf8" },
  card: {
    background: "rgba(255,255,255,0.05)",
    padding: "20px",
    borderRadius: "16px",
    width: "70%",
    margin: "auto",
    display: "flex",
    flexDirection: "column",
    gap: "12px",
  },
  heading: {
    textAlign: "left",
    color: "#94a3b8",
  },
  textarea: {
    height: "120px",
    background: "#020617",
    color: "white",
    border: "1px solid #334155",
    padding: "10px",
    borderRadius: "8px",
  },
  select: {
    padding: "10px",
    borderRadius: "8px",
    background: "#020617",
    color: "white",
  },
  primaryBtn: {
    background: "#3b82f6",
    padding: "10px",
    border: "none",
    borderRadius: "8px",
    color: "white",
    cursor: "pointer",
  },
  secondaryBtn: {
    background: "#9333ea",
    padding: "10px",
    border: "none",
    borderRadius: "8px",
    color: "white",
    cursor: "pointer",
  },
  resultCard: {
    marginTop: "20px",
    padding: "20px",
    background: "rgba(255,255,255,0.05)",
    borderRadius: "12px",
    width: "70%",
    marginLeft: "auto",
    marginRight: "auto",
  },
  output: {
    background: "#020617",
    padding: "10px",
    borderRadius: "8px",
    textAlign: "left",
    whiteSpace: "pre-wrap",
  },
  or: {
    color: "#64748b",
  },
};

export default Home;
